					databaseType.isCreateSchemaReturnsNegative(), databaseType.isCreateSchemaReturnsZero());
			stmtC += doCreateTestQueries(connection, databaseType, queriesAfter);
			return stmtC;
		} finally {
			connectionSource.releaseConnection(connection);
		}
	}
